int sceOpen(const char *, int);
int sceClose(int);
int sprintf(char *, const char *, ...);
int writeText(const int, char *);

enum {
  SCE_WRONLY = 2,
  SCE_CREAT = 0x200,
  SCE_TRUNC = 0x400
};

class rumbleManager
{
public:
  enum { RUMBLE_STATE_END = 12 };
  static const char regionNames[RUMBLE_STATE_END][30];
  char prefix[20];
  float rumbleLevels[RUMBLE_STATE_END];
  float rumbleVarPeriods[RUMBLE_STATE_END];
  float rumbleVarAmplitudes[RUMBLE_STATE_END];
  float rumbleFreqs[RUMBLE_STATE_END];
  void writeLevels();
};

void rumbleManager::writeLevels()
{
  int fout = sceOpen("host0:rumbleLevels.txt", SCE_WRONLY | SCE_TRUNC | SCE_CREAT);
  if (fout < 0)
    return;

  writeText(fout, "RumbleLevels\n");
  writeText(fout, "Location\t\tIntensity\tAmplitudeVariance\tPeriodVariance\tRumbleFreq\n");
  for (int i=0; i < RUMBLE_STATE_END; i++)
  {
    char textstr[200];
    sprintf(textstr, "%s\t\t%f\t%f\t%f\t%f\n", regionNames[i], rumbleLevels[i], rumbleVarAmplitudes[i], rumbleVarPeriods[i], rumbleFreqs[i]);
    writeText(fout, textstr);
  }
  sceClose(fout);
}
